WITH base AS (SELECT id, paid_at, status, CONCAT(status, ' - ', method) AS status_method, CASE WHEN status IN ('REFUNDED', 'SUCCESS') THEN 'Group A' ELSE 'Other' END AS status_group, COALESCE(method, 'UNKNOWN') AS method_filled FROM payments WHERE method IS NOT NULL AND method IS NOT DISTINCT FROM 'card') SELECT id, paid_at, status, status_method, status_group, method_filled FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY paid_at DESC NULLS LAST, id) AS rank_in_group FROM base) ranked WHERE rank_in_group = 1
